import numpy as np

class PackedTokenStream:
    # 把变长文档流拼成恰好 seq_len 的定长序列，消除 padding
    def __init__(self, docs, seq_len):
        self.buffer = []
        self.seq_len = seq_len
        for d in docs:
            self.buffer.extend(d)
            self.buffer.append(2)  # EOS 分隔符

    def __len__(self):
        return len(self.buffer) // (self.seq_len + 1)

    def __iter__(self):
        n = self.seq_len + 1
        for i in range(0, len(self.buffer) - n + 1, n):
            chunk = self.buffer[i:i + n]
            yield np.array(chunk[:-1]), np.array(chunk[1:])  # 输入与 shift 一位的标签

if __name__ == '__main__':
    rng = np.random.default_rng(0)
    docs = [rng.integers(3, 30000, size=rng.integers(50, 400)).tolist() for _ in range(64)]
    ds = PackedTokenStream(docs, seq_len=16)
    x, y = next(iter(ds))
    print('序列数:', len(ds), '输入形状:', x.shape, '标签形状:', y.shape)
    print('是否为下一个 token 预测:', bool((x[1:] == y[:-1]).all()))

