import torch
import torch.nn as nn

class Block(nn.Module):
    def __init__(self, d):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(d, 4 * d), nn.GELU(), nn.Linear(4 * d, d), nn.LayerNorm(d))

    def forward(self, x):
        return x + self.net(x)

class PipelineStage(nn.Module):
    # 只持有全局第 [start, end) 层的 Transformer 块
    def __init__(self, d, n_layers, start, end):
        super().__init__()
        self.layers = nn.ModuleList([Block(d) for _ in range(end - start)])

    def forward(self, x):
        for layer in self.layers:
            x = layer(x)
        return x

def split_layers(n_layers, n_stages):
    base, rest = divmod(n_layers, n_stages)
    bounds, cur = [], 0
    for i in range(n_stages):
        size = base + (1 if i < rest else 0)
        bounds.append((cur, cur + size))
        cur += size
    return bounds

if __name__ == '__main__':
    d, n_layers, n_stages = 64, 24, 4
    bounds = split_layers(n_layers, n_stages)
    stages = [PipelineStage(d, n_layers, s, e) for s, e in bounds]
    print('各 stage 层数区间:', bounds)
    x = torch.randn(2, 8, d)
    for i, st in enumerate(stages):
        x = st(x)
    print('流水线末端输出:', tuple(x.shape))
    print('气泡占比 (M=8):', round((n_stages - 1) / (8 + n_stages - 1), 3))

