def zero_stage_memory(n_params, n_gpu, stage):
    p = n_params
    if stage == 0:
        return 16 * p / 1e9
    if stage == 1:
        return (4 * p + 12 * p / n_gpu) / 1e9
    if stage == 2:
        return (2 * p + 14 * p / n_gpu) / 1e9
    return 16 * p / n_gpu / 1e9

