import torch

class KVCache:
    # 每层缓存 (B, n_kv_heads, S, head_dim) 的 K 与 V
    def __init__(self, n_layers, batch, n_kv_heads, head_dim, max_len, dtype=torch.float16, device='cpu'):
        self.k = [torch.zeros(batch, n_kv_heads, max_len, head_dim, dtype=dtype, device=device) for _ in range(n_layers)]
        self.v = [torch.zeros(batch, n_kv_heads, max_len, head_dim, dtype=dtype, device=device) for _ in range(n_layers)]
        self.seq_len = 0

    def append(self, layer, k_new, v_new):
        s = k_new.size(2)
        self.k[layer][:, :, self.seq_len:self.seq_len + s] = k_new
        self.v[layer][:, :, self.seq_len:self.seq_len + s] = v_new

    def advance(self, n):
        self.seq_len += n

    def nbytes(self):
        return sum(t.numel() * t.element_size() for t in self.k + self.v)

class BlockManager:
    # PagedAttention 的极简分页器：按 16 token 一块分配，支持前缀共享
    def __init__(self, n_blocks, block_size=16):
        self.block_size = block_size
        self.free = list(range(n_blocks))
        self.tables = {}

    def allocate(self, req_id, n_tokens):
        need = (n_tokens + self.block_size - 1) // self.block_size
        assert need <= len(self.free), 'out of KV blocks'
        self.tables[req_id] = [self.free.pop() for _ in range(need)]
        return self.tables[req_id]

    def free_req(self, req_id):
        self.free.extend(self.tables.pop(req_id))

def kv_cache_bytes(n_layers, seq_len, d_model, batch=1, dtype_bytes=2, n_kv_heads=None, head_dim=None):
    kv_dim = d_model if n_kv_heads is None else n_kv_heads * head_dim
    return 2 * n_layers * seq_len * kv_dim * dtype_bytes * batch

if __name__ == '__main__':
    for b in (1, 16, 64):
        gb = kv_cache_bytes(32, 4096, 4096, batch=b) / 1e9
        print(f'Llama-2-7B fp16, batch={b:>2}, 4096 token -> KV Cache {gb:.1f} GB')
    cache = KVCache(n_layers=2, batch=1, n_kv_heads=32, head_dim=128, max_len=64)
    cache.append(0, torch.randn(1, 32, 4, 128), torch.randn(1, 32, 4, 128))
    cache.advance(4)
    print('示例缓存大小 (MB):', round(cache.nbytes() / 1e6, 3), '已填充 token:', cache.seq_len)
    bm = BlockManager(n_blocks=100)
    print('请求 A 的物理块:', bm.allocate('A', 100), '剩余块:', len(bm.free))
    print('碎片率: 0%（按需分块，无预留）')

