def kv_budget(n_gpu_mem_gb, weight_gb, util=0.9, reserve_gb=1.5, per_seq_gb=2.1):
    usable = n_gpu_mem_gb * util - weight_gb - reserve_gb
    return round(usable, 2), max(0, int(usable // per_seq_gb))

