import random
from collections import defaultdict

def exact_match_acc(preds, golds):
    assert len(preds) == len(golds)
    hit = sum(p.strip().lower() == g.strip().lower() for p, g in zip(preds, golds))
    return hit / len(golds)

def win_rate(model_a, model_b, judge, swap=True):
    # judge(prompt, x, y) -> 'x' / 'y' / 'tie'；交换顺序消除位置偏置
    score = defaultdict(int)
    for prompt in model_a:
        a, b = model_a[prompt], model_b[prompt]
        v1 = judge(prompt, a, b)
        v2 = judge(prompt, b, a) if swap else 'tie'
        votes = []
        if v1 == 'x':
            votes.append('A')
        elif v1 == 'y':
            votes.append('B')
        if v2 == 'x':
            votes.append('B')     # 交换后判 x 说明原本 B 更好
        elif v2 == 'y':
            votes.append('A')
        if votes.count('A') > votes.count('B'):
            score['A'] += 1
        elif votes.count('B') > votes.count('A'):
            score['B'] += 1
        else:
            score['tie'] += 1
    n = len(model_a)
    return {k: round(v / n, 3) for k, v in score.items()}

def wilson_ci(k, n, z=1.96):
    p = k / n
    denom = 1 + z ** 2 / n
    centre = p + z ** 2 / (2 * n)
    margin = z * ((p * (1 - p) / n + z ** 2 / (4 * n ** 2)) ** 0.5)
    return round((centre - margin) / denom, 3), round((centre + margin) / denom, 3)

if __name__ == '__main__':
    preds = ['42', 'Paris', '7']
    golds = ['42', 'paris', '8']
    print('EM 准确率:', round(exact_match_acc(preds, golds), 3))

    random.seed(0)
    ma = {f'q{i}': f'answer A{i}' for i in range(200)}
    mb = {f'q{i}': f'answer B{i} shorter' for i in range(200)}
    judge = lambda p, x, y: 'x' if len(x) > len(y) else 'y'   # 模拟长度偏置裁判
    print('胜率(含长度偏置):', win_rate(ma, mb, judge))
    print('胜率 95% 置信区间 (k=120, n=200):', wilson_ci(120, 200))

